#[derive(clap::Args, Debug)]
pub(super) struct FleetCommand {
    /// Workspace root containing `.flux/fleet.toml` and durable fleet state.
    #[arg(long, value_name = "DIR", default_value = ".", global = true)]
    root: PathBuf,
    /// Output encoding. JSON/NDJSON, not human prose, is the automation API.
    #[arg(long, value_enum, default_value_t, global = true)]
    output: AgentOutput,
    /// Read one `flux.cli/v1` JSON request from a file or stdin (`-`).
    #[arg(long, value_name = "FILE|-", global = true)]
    request: Option<String>,
    /// Stable key for retrying a mutating request without applying it twice.
    #[arg(long, global = true)]
    idempotency_key: Option<String>,
    /// Refuse a mutation unless fleet state still has this revision.
    #[arg(long, global = true)]
    if_revision: Option<String>,
    /// Validate and return the proposed result without writing.
    #[arg(long, global = true)]
    dry_run: bool,
    #[command(subcommand)]
    action: FleetAction,
}

#[derive(clap::Subcommand, Debug)]
pub(super) enum FleetAction {
    Init {
        #[arg(long, default_value_t = 3)]
        max_workers: usize,
        #[arg(long, default_value_t = 10)]
        max_wave: usize,
        #[arg(long, default_value_t = 2)]
        max_rework: usize,
    },
    /// Diagnose configuration AND runtime health, read-only.
    ///
    /// Beyond `validate`'s configuration checks, reports agents recorded active whose supervisor is
    /// gone, waves wedged mid-integration, worktrees a topology names that disk lacks, items claimed by
    /// more than one live wave, story worktrees holding work no commit has, and branches left at their
    /// pinned base holding nothing unique. Each finding carries its own next action; runtime findings do
    /// not fail the run, so `data.runtime` is the machine-readable verdict.
    Doctor,
    Refresh,
    /// Reclaim a finished wave's build output, and its worktrees if they provably hold no work.
    ///
    /// Acceptance reclaims automatically; this is for the waves that ended some other way — parked,
    /// failed, conflicted — which otherwise keep their target directories for as long as the checkout
    /// exists. Disk is what caps fleet width, so those are not free.
    Reclaim {
        /// Wave to reclaim. Omit to reclaim every wave that is not in flight.
        target: Option<String>,
    },
    /// Rebuild the structure a wave's topology names and disk lacks, discarding nothing.
    ///
    /// A worktree removed out from under an unfinished wave, or one left off the base it is pinned
    /// to, currently takes a hand-written `git worktree add` or `git reset --hard` against values
    /// read out of `state.json`. Every input is already recorded, so this is a verb.
    Repair {
        /// Wave whose recorded structure should be rebuilt.
        wave: String,
    },
    /// Commit the work a story worker left uncommitted onto that story's own branch.
    ///
    /// The recovery half of a story worktree. An interrupted turn leaves its work uncommitted —
    /// that is the normal state, not a failure — and until now saving it took hand-running `git add`
    /// and `git commit` inside a directory the fleet owns, which the operating rules forbid and no
    /// operator should have to improvise under time pressure. Every input is already recorded: the
    /// checkout, the branch it is on, and the story it belongs to.
    Capture {
        /// Wave whose story worktrees should be captured.
        wave: String,
        /// Capture only this story. Omit to capture every story worktree of the wave that holds work.
        #[arg(long, value_name = "BOARD/ITEM")]
        item: Option<String>,
        /// Commit subject. A default naming the wave and the story is used when omitted.
        #[arg(long)]
        message: Option<String>,
    },
    Validate,
    Start,
    Stop,
    /// Stop dispatch and confirm no worker turn is in flight, so a new binary can be installed.
    ///
    /// The recorded quiesce refuses every dispatch until `flux fleet resume` lifts it, and the
    /// command itself fails while a worker is still moving — so `flux fleet quiesce && install`
    /// cannot proceed into a live wave.
    Quiesce {
        /// Why the fleet is being quiesced. Recorded on the state and in the journal.
        #[arg(long)]
        reason: Option<String>,
    },
    /// Record and inspect goals the main coordinator must use for every planning decision.
    Goal {
        #[command(subcommand)]
        action: FleetGoalAction,
    },
    /// Submit a user requirement, task, or agent follow-up to the main coordinator inbox.
    Ingest {
        text: String,
        #[arg(long, value_enum, default_value_t)]
        source: IntakeSource,
        #[arg(long, default_value = "user")]
        from: String,
        /// Acknowledgement boundary. `accepted` only journals; later levels run the main turn.
        #[arg(long, value_enum, default_value_t = AckLevel::Accepted)]
        wait: AckLevel,
    },
    /// Admit a template-based or ad-hoc worker through the main coordinator.
    Spawn {
        #[arg(long)]
        template: Option<String>,
        #[arg(long)]
        role: Option<String>,
        #[arg(long, conflicts_with = "instructions_file")]
        instructions: Option<String>,
        #[arg(long, conflicts_with = "instructions")]
        instructions_file: Option<PathBuf>,
        #[arg(long)]
        model: Option<String>,
        #[arg(long, value_name = "BOARD/ITEM")]
        item: Option<String>,
        #[arg(long, value_enum)]
        mode: Option<FleetTaskMode>,
        #[arg(long)]
        name: Option<String>,
        #[arg(long = "capability")]
        capabilities: Vec<String>,
        #[arg(long = "fence")]
        fences: Vec<String>,
    },
    Run {
        #[arg(value_name = "BOARD/ITEM")]
        items: Vec<String>,
        /// Build the durable wave/worktrees without launching agents (for manual/offline handoff).
        #[arg(long)]
        prepare_only: bool,
    },
    /// Verify a story worker's exact commit, write set and targeted validation evidence.
    Handoff {
        wave: String,
        #[arg(value_name = "BOARD/ITEM")]
        item: String,
        #[arg(long)]
        commit: String,
        #[arg(long)]
        worker: Option<String>,
        #[arg(long)]
        session: Option<String>,
        /// Derive the write set from `base..HEAD` instead of restating what the range already proves.
        #[arg(long, conflicts_with = "write_set")]
        from_worktree: bool,
        #[arg(long = "write-set", value_name = "PATH")]
        write_set: Vec<String>,
        #[arg(long = "test-arg", value_name = "ARGV", allow_hyphen_values = true)]
        test_argv: Vec<String>,
        #[arg(long)]
        failing_before: bool,
        #[arg(long)]
        passing_after: bool,
        #[arg(long)]
        no_failing_test_reason: Option<String>,
        /// Cite the Acceptance criterion this handoff claims, by its `AC-n` id. Repeat for more.
        ///
        /// C-739. Optional, and a story whose criteria carry no ids has none to cite. An id the
        /// story does not declare at the handed-off commit is refused rather than recorded.
        #[arg(long = "criterion", value_name = "AC-N")]
        criteria: Vec<String>,
        #[arg(long)]
        summary: String,
    },
    /// Report which Acceptance criteria are claimed, by which commit, and on what evidence.
    Coverage {
        #[arg(value_name = "BOARD/ITEM")]
        item: String,
    },
    /// Have an agent that is not the writer examine each candidate, and record its typed verdict.
    ///
    /// C-587. Nothing adversarial used to read a Fleet candidate: `rework` took a `--reviewer`
    /// string, so "reviewer" named a field a finding could cite rather than an agent anyone
    /// dispatched. The reviewer admitted here is fresh, read-only, and given one packet — the story
    /// contract at the reviewed commit plus the exact normalized diff — and nothing else. Its
    /// `PASS` at the exact handoff commit is what `integrate` now requires.
    Review {
        wave: String,
        /// Review only this candidate. Omit to review every candidate of the wave still owed one.
        #[arg(long, value_name = "BOARD/ITEM")]
        item: Option<String>,
        /// Record an external reviewer's typed `flux.fleet-review/v1` document instead of
        /// dispatching one. Validated identically, and refused when it names the story's own writer.
        #[arg(long, value_name = "FILE|-")]
        from: Option<String>,
    },
    /// Return structured review findings to the same worker session; the third request parks.
    Rework {
        wave: String,
        #[arg(value_name = "BOARD/ITEM")]
        item: String,
        #[arg(long)]
        reviewer: String,
        #[arg(long)]
        reviewed_commit: String,
        #[arg(long = "path", value_name = "PATH:LINE:DETAIL")]
        paths: Vec<String>,
        #[arg(long = "command-output")]
        command_outputs: Vec<String>,
        #[arg(long = "invariant")]
        invariants: Vec<String>,
    },
    /// Assemble accepted story commits and run each repository's final gate exactly once.
    Integrate {
        wave: String,
    },
    Task {
        target: String,
        instruction: String,
        #[arg(long, value_enum, default_value_t)]
        mode: FleetTaskMode,
        /// Acknowledgement boundary. Completed is the safe default for one-shot automation.
        #[arg(long, value_enum, default_value_t)]
        wait: AckLevel,
    },
    Message {
        target: String,
        message: String,
        #[arg(long, value_enum, default_value_t)]
        wait: AckLevel,
    },
    Cancel {
        target: String,
    },
    /// Park a wave with a recorded reason, so it stops being re-decided while a human deliberates.
    ///
    /// Parking used to be a line in a driver-owned text file: invisible to `fleet status`, so the
    /// coordinator re-decided a parked wave every minute, and unparking meant editing text.
    Park {
        wave: String,
        /// Why the wave is paused. Recorded on the wave and reported by `fleet status`.
        #[arg(long)]
        reason: String,
    },
    /// Return a parked wave to the lifecycle state it held when it was parked.
    Unpark {
        wave: String,
    },
    /// Move a wave out of a delivery status whose preconditions never held.
    ///
    /// C-721. A wave recorded `applied` whose canonical ref never gained its commits is unreachable:
    /// `apply` refuses it for no longer being green and `integrate` refuses it as not ready, so the
    /// stranded work could only be recovered by hand-editing state or hand-merging a branch. This
    /// verifies the claim against git first and refuses a wave that really did deliver.
    Reopen {
        wave: String,
        /// Why it is being reopened. Recorded on the wave and in the durable event.
        #[arg(long)]
        reason: Option<String>,
    },
    Resume {
        target: Option<String>,
    },
    /// Merge a recorded green local candidate. Never pushes, releases or deploys.
    Apply {
        wave: String,
        /// Accept only this repository's candidate, from a wave whose other repositories failed.
        ///
        /// Integration is per repository and produces one candidate each, so a wave can hold a green
        /// candidate beside a conflicted one. Without this, that green candidate was unreachable: apply
        /// demanded the whole wave be green, and an independent repository's delivered work was stranded
        /// by a collision it had no part in.
        #[arg(long)]
        only: Option<String>,
    },
    /// Land every member's accepted candidates on its LOCAL canonical branch, in dependency order.
    ///
    /// C-681. `apply` accepts and pins; this is the step that writes the branch. Per member, in the
    /// order `depends_on` declares: accumulate the accepted candidates that the canonical ref does not
    /// already contain, merge them in a throwaway worktree branched from that ref, gate the result
    /// there, and only then advance the branch — by a compare-and-swap ref update, so no working tree
    /// anywhere is touched. A conflicting candidate is left out and named. A red gate anywhere leaves
    /// EVERY member's branch untouched. Nothing is pushed, released or deployed.
    Promote {
        /// Promote only this repository.
        #[arg(long)]
        only: Option<String>,
    },
    Status,
    Schedule,
    /// Run the unattended driver: one deterministic tick, or an interval loop over it.
    ///
    /// C-631. The driver was a 582-line bash script that parsed `state.json` three separate ways with
    /// no `--if-revision` guard, could not be edited while running, and needed a production failure to
    /// find each of its defects. Its judgment always lived outside it — planner, retro and scribe are
    /// authored `.flux` loops it invoked host-side — so this inherits those unchanged and owns only
    /// tick mechanics: report, advance, accumulate, dispatch.
    Drive {
        /// Perform exactly one tick and exit. The default when neither flag is given.
        #[arg(long)]
        tick: bool,
        /// Repeat the tick on an interval, under a durable single-instance guard.
        #[arg(long = "loop", conflicts_with = "tick")]
        run_loop: bool,
        /// Seconds between ticks under `--loop`.
        #[arg(long, default_value_t = 60, value_name = "SECONDS")]
        interval: u64,
        /// Stop after this many ticks under `--loop`; `0` runs until the fleet is stopped or quiesced.
        #[arg(long, default_value_t = 0)]
        max_ticks: u64,
    },
    /// Show unresolved human decisions without stopping unrelated work.
    Decisions {
        /// Queue unresolved decisions for an independent adversarial decision agent.
        #[arg(long)]
        auto: bool,
    },
    Events {
        #[arg(long)]
        follow: bool,
        #[arg(long, default_value_t = 200)]
        limit: usize,
    },
    Logs {
        target: Option<String>,
        #[arg(long, default_value_t = 200)]
        limit: usize,
    },
    Note {
        text: String,
    },
    Agents,
    Worktrees,
    Inspect {
        #[arg(value_enum)]
        view: InspectView,
        target: Option<String>,
        /// `inspect gate` only: narrow a wave's gate output to one repository of its topology.
        #[arg(long)]
        repository: Option<String>,
        #[arg(long, default_value_t = 200)]
        limit: usize,
    },
    Dashboard,
    Schema,
    Call {
        operation: String,
    },
    Skill,
}

#[derive(clap::Subcommand, Debug)]
