#[derive(clap::ValueEnum, Clone, Copy, Debug, Default, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "kebab-case")]
pub(super) enum GoalScope {
    Values,
    Company,
    Workspace,
    #[default]
    Project,
    Repository,
}

impl GoalScope {
    fn as_str(self) -> &'static str {
        match self {
            Self::Values => "values",
            Self::Company => "company",
            Self::Workspace => "workspace",
            Self::Project => "project",
            Self::Repository => "repository",
        }
    }
}

#[derive(clap::ValueEnum, Clone, Copy, Debug, Default, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "kebab-case")]
pub(super) enum IntakeSource {
    #[default]
    User,
    Agent,
    Automation,
}

#[derive(clap::ValueEnum, Clone, Copy, Debug, Default, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "kebab-case")]
pub(super) enum FleetTaskMode {
    #[default]
    ReadOnly,
    Write,
}

#[derive(clap::ValueEnum, Clone, Copy, Debug, Default, PartialEq, Eq, Serialize)]
#[serde(rename_all = "lowercase")]
pub(super) enum AckLevel {
    Accepted,
    Delivered,
    #[default]
    Completed,
}

#[derive(clap::ValueEnum, Clone, Copy, Debug)]
pub(super) enum InspectView {
    Snapshot,
    Wave,
    Worker,
    Result,
    Activity,
    Worktree,
    Integration,
    /// A wave's repository gates: argv, exit code and the gate's own captured output, tail first.
    Gate,
    Source,
    Search,
    Story,
    PullRequest,
}

#[derive(Clone, Debug, Serialize)]
struct Story {
    id: String,
    title: String,
    status: String,
    /// C-741: what kind of work this is, which selects the contract it is validated against.
    ///
    /// Always resolved, never absent, so every reader handed an item sees a kind rather than having
    /// to know the default. A story that predates the field reads as `feature`, which is how the
    /// field can be added without invalidating a single existing story.
    kind: String,
    file: String,
    pillar: Option<String>,
    epic: Option<String>,
    design: Option<String>,
    areas: Vec<String>,
    note: Option<String>,
    priority: Option<i64>,
    dependencies: Vec<String>,
    #[serde(skip)]
    body: String,
}

#[derive(Clone, Debug, PartialEq, Serialize, Deserialize)]
struct FleetState {
    schema: String,
    revision: u64,
    running: bool,
    #[serde(default)]
    main_agent: MainAgentState,
    #[serde(default)]
    goals: BTreeMap<String, FleetGoal>,
    #[serde(default)]
    intake: BTreeMap<String, Value>,
    /// Worker agents only. The unique coordinator is always `main_agent`.
    #[serde(default)]
    agents: BTreeMap<String, Value>,
    #[serde(default)]
    waves: BTreeMap<String, Value>,
    /// C-642: the recorded maintenance window. `Some` means dispatch is stopped until
    /// `flux fleet resume` lifts it. `default` keeps state files written before it existed loadable.
    #[serde(default)]
    quiesce: Option<QuiesceRecord>,
    /// C-631: what the unattended driver has already done, so a tick is comparable to the last one.
    ///
    /// The bash driver kept this in files beside the state — a pidfile, a tick counter, a
    /// last-status text blob — which is why three parsers disagreed about the same fleet. `default`
    /// keeps state files written before it existed loadable.
    #[serde(default)]
    drive: Option<DriveRecord>,
    #[serde(default)]
    idempotency: BTreeMap<String, StoredResult>,
}

/// C-631: the durable record one `flux fleet drive` tick leaves behind.
#[derive(Clone, Debug, Default, PartialEq, Serialize, Deserialize)]
struct DriveRecord {
    /// Ticks this fleet has run. Monotonic, and the tick number reported by each result.
    ticks: u64,
    /// Fingerprint of the state the previous tick decided on.
    ///
    /// A tick whose fingerprint is unchanged decided on exactly the same facts, which is what makes
    /// an idle tick provable instead of inferred from the absence of output.
    #[serde(default)]
    fingerprint: Option<String>,
    /// The fleet revision the previous tick observed.
    #[serde(default)]
    revision: u64,
    /// C-723: how long each ready item has been withheld, keyed by item.
    ///
    /// A withhold is the only silent thing a tick does — the item leaves the schedulable pool and
    /// the tick reports a smaller dispatch count, not a missing story — so the run has to be
    /// recorded before `fleet doctor` can be asked about it. Pruned to the items the current tick
    /// withheld rather than accumulated: a map that only grows is how one state file reached 12.9MB.
    #[serde(default)]
    withheld: BTreeMap<String, DriveWithhold>,
    /// C-728: how long each eligible item has gone undispatched, keyed by item.
    ///
    /// Deliberately independent of [`DriveRecord::withheld`]: that map only holds items a tick
    /// judged and named, and the failure this answers is an item no tick judged at all. Counting
    /// what dispatch did NOT send is the one measure that cannot be fooled by an accounting gap,
    /// because it is derived from the eligible pool rather than from the reasons about it. Pruned
    /// to the current pool for the same reason `withheld` is: a map that only grows is how one
    /// state file reached 12.9MB.
    #[serde(default)]
    undispatched: BTreeMap<String, DriveUndispatched>,
}

/// C-723: one ready item's unbroken run of withheld ticks.
#[derive(Clone, Debug, Default, PartialEq, Serialize, Deserialize)]
struct DriveWithhold {
    /// The reason the most recent tick gave. A different reason starts a new run.
    reason: String,
    /// Consecutive ticks withheld on that reason.
    ticks: u64,
    /// The tick the run started at, so a reader can date it against the journal.
    since_tick: u64,
}

/// C-728: one eligible item's unbroken run of ticks that did not dispatch it.
#[derive(Clone, Debug, Default, PartialEq, Serialize, Deserialize)]
struct DriveUndispatched {
    /// The reason the most recent tick recorded, when it recorded one at all.
    ///
    /// `None` is the whole signature of this story's defect: the item was eligible, it was not
    /// sent, and no tick said why.
    #[serde(default)]
    reason: Option<String>,
    /// Consecutive ticks the item was eligible and went unsent. A reason that changes does not
    /// restart it — the question here is whether anything ever dispatched the item, not whether
    /// one judgement about it held.
    ticks: u64,
    /// The tick the run started at, so a reader can date it against the journal.
    since_tick: u64,
}

/// C-642: the durable fact that dispatch is stopped, and why.
///
/// Recorded rather than derived, because process absence and a deliberate pause were previously
/// indistinguishable: the operator's "is anything running?" test was a process-table scan, and a
/// `pgrep` that matched its own shell reported idle while three workers ran.
#[derive(Clone, Debug, PartialEq, Serialize, Deserialize)]
struct QuiesceRecord {
    /// Operator-supplied cause, redacted like every other recorded string.
    #[serde(default)]
    reason: Option<String>,
    /// The fleet revision this quiesce was recorded at, so the journal can be ordered against it.
    since_revision: u64,
}

#[derive(Clone, Debug, PartialEq, Serialize, Deserialize)]
struct MainAgentState {
    id: String,
    role: String,
    status: String,
    session: Option<String>,
    intake_sequence: u64,
    goals_revision: u64,
    #[serde(default)]
    last_turn: Option<Value>,
    #[serde(default)]
    last_error: Option<String>,
    /// The coordinator's recorded scope: mode, operation count, and the repository roots it holds.
    ///
    /// C-610. The ceiling was always enforced at spawn, but the record did not exist as a field at all,
    /// so `state.json` described every constrained worker and stayed silent about the privileged agent.
    /// An absent record is indistinguishable from an absent ceiling — auditing the fleet led to exactly
    /// the wrong conclusion about which agent was confined. `default` keeps older state files loadable.
    #[serde(default)]
    capability_set: Option<Value>,
    /// C-600: the transcript segments this coordinator has retired, oldest first.
    ///
    /// The coordinator's durable session is an *operator* artifact, and it had no lifecycle: the
    /// model never reads it back and compaction is structurally unreachable for an authored loop, so
    /// one recorded session reached 8.2 MB after ~75 intake items and kept growing. Rolling over is
    /// the bound; this index is how a retired segment stays findable afterwards. The transcripts
    /// themselves are never deleted — every segment is minted in the SAME store, so
    /// `flux sessions --store <git-dir>/flux-fleet/sessions/main` and the TUI session picker still
    /// list all of them. The index is bounded because a list that only grows is how one state file
    /// reached 12.9MB; the store, not this field, is the durable record.
    #[serde(default)]
    session_history: Vec<String>,
}

impl Default for MainAgentState {
    fn default() -> Self {
        Self {
            id: "main".into(),
            role: "coordinator".into(),
            status: "stopped".into(),
            session: None,
            intake_sequence: 0,
            goals_revision: 0,
            last_turn: None,
            last_error: None,
            capability_set: None,
            session_history: Vec::new(),
        }
    }
}

impl MainAgentState {
    /// Record the coordinator's current transcript segment, retaining the one it replaces.
    ///
    /// C-600: a rollover must never lose operator history, so the id being replaced is pushed onto
    /// the index rather than overwritten. Recording the same id again is a resume, not a roll.
    fn record_session(&mut self, session: Option<String>) {
        let replaced = self
            .session
            .take()
            .filter(|previous| session.as_deref() != Some(previous.as_str()));
        if let Some(previous) = replaced {
            self.session_history.push(previous);
            let overflow = self
                .session_history
                .len()
                .saturating_sub(COORDINATOR_TRANSCRIPT_HISTORY);
            self.session_history.drain(..overflow);
        }
        self.session = session;
    }
}

