    /// A fleet that is running, with no worker in flight and no wave claiming anything.
    fn drive_fixture_state() -> FleetState {
        FleetState {
            running: true,
            ..Default::default()
        }
    }

    fn drive_fixture_schedule(items: &[&str]) -> Value {
        json!({"waves": [{"id": "ready", "state": "active", "eligible": items}]})
    }

    /// C-631: the whole point of the reconcile gate. `wave-472` dispatched ten stories whose work was
    /// already in `main` because an unread already-built set reads exactly like an empty one, so a tick
    /// that cannot read reconcile must send nobody and say why.
    #[test]
    fn drive_dispatch_fails_closed_when_board_reconcile_cannot_be_read() {
        let state = drive_fixture_state();
        let schedule = drive_fixture_schedule(&["flux/C-1", "flux/C-2"]);

        let plan = drive_tick_plan(&state, &schedule, None, 3);

        assert!(plan.dispatch.is_empty(), "{:?}", plan.dispatch);
        let blocked = plan.blocked.expect("a refusal names what is missing");
        assert!(blocked.contains("board reconcile"), "{blocked}");
        assert!(blocked.contains("indistinguishable"), "{blocked}");
    }

    /// A story whose implementation is already present is WITHHELD and named, never silently dropped.
    ///
    /// C-723 added the `withhold` verdict: reconcile proposes, verification disposes, and only a
    /// finding that survived verification may take an item out of the schedulable pool.
    #[test]
    fn drive_dispatch_withholds_an_item_whose_work_is_already_present() {
        let state = drive_fixture_state();
        let schedule = drive_fixture_schedule(&["flux/C-1", "flux/C-2"]);
        let reconcile = json!({"findings": [{
            "id": "flux/C-1",
            "signals": ["commit-subject"],
            "transition_path": ["in-progress", "done"],
            "withhold": {
                "verified": true,
                "detail": "4 of 4 Acceptance criteria ticked and every named artifact is present",
                "evidence": [{"artifact": "AlreadyThere", "present": true}],
            },
        }]});

        let plan = drive_tick_plan(&state, &schedule, Some(&reconcile), 3);

        assert_eq!(plan.dispatch, vec!["flux/C-2".to_string()]);
        assert_eq!(plan.withheld.len(), 1);
        assert_eq!(plan.withheld[0]["item"], "flux/C-1");
        assert_eq!(plan.withheld[0]["reason"], "already-built");
        assert_eq!(plan.withheld[0]["signals"], json!(["commit-subject"]));
        assert_eq!(
            plan.withheld[0]["evidence"],
            json!([{"artifact": "AlreadyThere", "present": true}]),
            "a withheld item reports what justified withholding it: {:?}",
            plan.withheld[0]
        );
        assert!(plan.overridden.is_empty(), "{:?}", plan.overridden);
        assert!(plan.blocked.is_none());
    }

    /// C-723, failing first: the live tick, reproduced. Eight free slots, nine ready items, and
    /// `board reconcile` naming two of them — and the fleet dispatched one.
    ///
    /// `already-built` is not a fact the driver verifies; it is reconcile's heuristic, and C-718
    /// establishes that the heuristic matches a *mention* of a story id rather than an
    /// implementation. `C-544`'s sole evidence was a sibling story's feature commit and `C-570`'s
    /// was a forward-referencing doc comment, yet both left the schedulable pool every tick.
    ///
    /// Withholding is the strongest action a tick takes and the only silent one, so it fails closed
    /// toward dispatching: a finding that carries no verification does not withhold. Eight slots
    /// fill, and the ninth item waits on width — a fact about the fleet — rather than on a guess
    /// about the tree.
    #[test]
    fn drive_dispatches_an_item_whose_already_built_signal_carries_no_verification() {
        let ready = [
            "flux/C-544",
            "flux/C-570",
            "flux/C-601",
            "flux/C-602",
            "flux/C-603",
            "flux/C-604",
            "flux/C-605",
            "flux/C-606",
            "exchange/X-139",
        ];
        let state = drive_fixture_state();
        let schedule = drive_fixture_schedule(&ready);
        let reconcile = json!({"findings": [
            {
                "id": "flux/C-544",
                "signals": ["implementation-landed"],
                "transition_path": ["in-progress", "done"],
            },
            {
                "id": "flux/C-570",
                "signals": ["implementation-landed"],
                "transition_path": ["in-progress", "done"],
            },
        ]});

        let plan = drive_tick_plan(&state, &schedule, Some(&reconcile), 8);

        assert_eq!(plan.width, 8, "eight workers are free");
        assert_eq!(
            plan.dispatch.len(),
            8,
            "eight free slots must fill; unverified reconcile findings are not a block: {:?}",
            plan.dispatch
        );
        assert!(
            plan.dispatch.contains(&"flux/C-544".to_string())
                && plan.dispatch.contains(&"flux/C-570".to_string()),
            "the two withheld fixtures are exactly the ones that must dispatch: {:?}",
            plan.dispatch
        );
        assert!(
            plan.withheld
                .iter()
                .all(|entry| entry["reason"] == json!("width")),
            "the only item held back is held on capacity, not on a heuristic: {:?}",
            plan.withheld
        );
    }

    /// C-723: a released signal is reported, not swallowed. A wrong withhold has to be readable in
    /// the tick output — the failure mode being fixed is one whose only symptom was a smaller number.
    #[test]
    fn drive_reports_the_evidence_behind_every_released_already_built_signal() {
        let state = drive_fixture_state();
        let schedule = drive_fixture_schedule(&["flux/C-570"]);
        let reconcile = json!({"findings": [{
            "id": "flux/C-570",
            "signals": ["implementation-landed"],
            "transition_path": ["in-progress", "done"],
            "withhold": {
                "verified": false,
                "detail": "the Acceptance names 1 artifact(s) this checkout does not have \
                           (AgentReport); the signal is a mention of the id, not its implementation",
                "evidence": [{"artifact": "AgentReport", "present": false}],
            },
        }]});

        let plan = drive_tick_plan(&state, &schedule, Some(&reconcile), 8);

        assert_eq!(plan.dispatch, vec!["flux/C-570".to_string()]);
        assert!(plan.withheld.is_empty(), "{:?}", plan.withheld);
        assert_eq!(plan.overridden.len(), 1, "{:?}", plan.overridden);
        assert_eq!(plan.overridden[0]["item"], "flux/C-570");
        assert_eq!(plan.overridden[0]["reason"], "already-built");
        assert_eq!(
            plan.overridden[0]["evidence"],
            json!([{"artifact": "AgentReport", "present": false}]),
            "the concrete evidence travels with the release: {:?}",
            plan.overridden[0]
        );
        assert!(
            plan.overridden[0]["detail"]
                .as_str()
                .is_some_and(|detail| detail.contains("AgentReport")),
            "{:?}",
            plan.overridden[0]
        );
    }

    /// An item a live wave still holds an attempt at is not a second wave's to take.
    #[test]
    fn drive_dispatch_withholds_an_item_a_live_wave_still_claims() {
        let mut state = drive_fixture_state();
        state.waves.insert(
            "wave-9".into(),
            json!({"status": "awaiting-handoffs", "items": ["flux/C-2"]}),
        );
        let schedule = drive_fixture_schedule(&["flux/C-1", "flux/C-2"]);
        let reconcile = json!({"findings": []});

        let plan = drive_tick_plan(&state, &schedule, Some(&reconcile), 3);

        assert_eq!(plan.dispatch, vec!["flux/C-1".to_string()]);
        assert_eq!(plan.withheld[0]["item"], "flux/C-2");
        assert_eq!(plan.withheld[0]["reason"], "claimed");
        assert!(
            plan.withheld[0]["detail"]
                .as_str()
                .unwrap()
                .contains("wave-9"),
            "{:?}",
            plan.withheld[0]
        );
    }

    /// A parked wave keeps its claim — the work is still on disk and the pause is a human's to answer
    /// — but the driver must name the park and its reason rather than report it as live work.
    #[test]
    fn drive_dispatch_names_the_park_that_holds_an_item_rather_than_a_generic_claim() {
        let mut state = drive_fixture_state();
        state.waves.insert(
            "wave-9".into(),
            json!({
                "status": "parked",
                "items": ["flux/C-2"],
                "park": {"reason": "waiting on the API decision"},
            }),
        );
        let schedule = drive_fixture_schedule(&["flux/C-1", "flux/C-2"]);

        let plan = drive_tick_plan(&state, &schedule, Some(&json!({"findings": []})), 3);

        assert_eq!(plan.dispatch, vec!["flux/C-1".to_string()]);
        assert_eq!(plan.withheld[0]["item"], "flux/C-2");
        assert_eq!(plan.withheld[0]["reason"], "parked");
        let detail = plan.withheld[0]["detail"].as_str().unwrap();
        assert!(detail.contains("wave-9"), "{detail}");
        assert!(detail.contains("waiting on the API decision"), "{detail}");

        // Ending the wave releases the claim; the item is dispatchable again.
        state.waves.insert(
            "wave-9".into(),
            json!({"status": "cancelled", "items": ["flux/C-2"]}),
        );
        let released = drive_tick_plan(&state, &schedule, Some(&json!({"findings": []})), 3);
        assert_eq!(
            released.dispatch,
            vec!["flux/C-1".to_string(), "flux/C-2".to_string()]
        );
    }

    /// A pid that is certainly dead: run a child to completion and reap it.
    ///
    /// Never a nonsense value instead — `u32::MAX` narrows to `-1`, which `kill` reads as "every
    /// process this user may signal", so it reports success and every assertion built on it inverts.
    fn reaped_supervisor_pid() -> u32 {
        let child = std::process::Command::new("true")
            .spawn()
            .expect("spawn a trivial child");
        let pid = child.id();
        let mut child = child;
        child.wait().expect("reap it");
        pid
    }

    /// The `wave-745` record as the fleet actually held it.
    ///
    /// Two stories claimed, no handoff recorded against either, and both workers left `working` by one
    /// supervisor pid. `pid` is what makes the fixture a fixture: pass this process to describe a wave
    /// that is genuinely running, pass a reaped one to describe the overnight crash.
    fn wave_745_fixture(pid: u32) -> FleetState {
        let mut state = drive_fixture_state();
        state.waves.insert(
            "wave-745".into(),
            json!({
                "id": "wave-745",
                "status": "awaiting-handoffs",
                "items": ["flux/C-575", "flux/C-519"],
                "topology": {"repositories": [{
                    "id": "flux",
                    "stories": [
                        {"board_ref": "flux/C-575", "handoff": Value::Null},
                        {"board_ref": "flux/C-519", "handoff": Value::Null},
                    ],
                }]},
            }),
        );
        for (id, board_ref) in [
            ("wave-745-worker-1", "flux/C-575"),
            ("wave-745-worker-2", "flux/C-519"),
        ] {
            state.agents.insert(
                id.into(),
                json!({
                    "id": id,
                    "status": "working",
                    "supervisor_pid": pid,
                    "assignment": {"wave": "wave-745", "board_ref": board_ref},
                }),
            );
        }
        state
    }

    /// C-724 (failing first): a claim must not outlive the process that holds it.
    ///
    /// `wave-745`'s supervisor — pid 3513527 — died overnight and the wave went on claiming `C-575`
    /// and `C-519` against a process that no longer existed. Those two stories sat at the TOP of a
    /// ready board while 70 of the next 82 drive ticks reported an empty dispatch queue. Nothing
    /// reclaimed the claim, so a driver crash removed its in-flight items from the schedulable pool
    /// permanently — the opposite of what an unattended machine should do with an interrupted turn.
    ///
    /// The release is the TICK's, not an operator's: this asserts the plan a tick computes from
    /// durable state alone, with no command typed in between.
    #[test]
    fn a_wave_whose_supervisor_is_gone_releases_its_claim_on_the_next_tick() {
        let dead_pid = reaped_supervisor_pid();
        let schedule = drive_fixture_schedule(&["flux/C-575", "flux/C-519", "flux/C-1"]);
        let reconcile = json!({"findings": []});

        // The control, and the whole reason a claim exists: a wave whose supervisor is running holds
        // its two stories against every other wave, and only the unclaimed item dispatches.
        let live = wave_745_fixture(std::process::id());
        let held = drive_tick_plan(&live, &schedule, Some(&reconcile), 8);
        assert_eq!(
            held.dispatch,
            vec!["flux/C-1".to_string()],
            "a live wave's claim is not the driver's to take"
        );
        assert!(held.released.is_empty(), "{:?}", held.released);

        // The defect: the same record, one dead pid.
        let state = wave_745_fixture(dead_pid);
        let plan = drive_tick_plan(&state, &schedule, Some(&reconcile), 8);

        assert_eq!(
            plan.dispatch,
            vec![
                "flux/C-575".to_string(),
                "flux/C-519".to_string(),
                "flux/C-1".to_string()
            ],
            "wave-745 claims C-575 and C-519 against pid {dead_pid}, which no longer exists, so \
             both are schedulable again; withheld was {:?}",
            plan.withheld
        );
        assert!(
            !plan
                .withheld
                .iter()
                .any(|withheld| withheld["reason"] == "claimed"),
            "nothing is withheld as claimed once the claim is released: {:?}",
            plan.withheld
        );
        // The release is reported as its own verified effect, naming the pid that proves it.
        assert_eq!(plan.released.len(), 1, "{:?}", plan.released);
        assert_eq!(plan.released[0]["wave"], json!("wave-745"));
        assert_eq!(plan.released[0]["supervisor_pid"], json!(dead_pid));
        assert_eq!(
            plan.released[0]["items"],
            json!(["flux/C-575", "flux/C-519"])
        );

        // Delivered work keeps its claim however dead the supervisor is. A wave holding an accepted
        // handoff has commits waiting for an integrator, and starting a second attempt at that story
        // is precisely the double-write the claim exists to prevent.
        let mut delivered = wave_745_fixture(dead_pid);
        delivered.waves.get_mut("wave-745").unwrap()["topology"]["repositories"][0]["stories"][0]
            ["status"] = json!("handoff-accepted");
        let plan = drive_tick_plan(&delivered, &schedule, Some(&reconcile), 8);
        assert!(plan.released.is_empty(), "{:?}", plan.released);
        assert_eq!(plan.dispatch, vec!["flux/C-1".to_string()]);

        // A park is a decision a human owns, and a dead driver does not answer it.
        let mut parked = wave_745_fixture(dead_pid);
        parked.waves.get_mut("wave-745").unwrap()["status"] = json!("parked");
        let plan = drive_tick_plan(&parked, &schedule, Some(&reconcile), 8);
        assert!(plan.released.is_empty(), "{:?}", plan.released);
        assert_eq!(plan.withheld[0]["reason"], "parked");

        // A record written before the pid field existed is judged as live, never released: an
        // unanswered question is not a licence to take another wave's story.
        let mut legacy = wave_745_fixture(dead_pid);
        legacy.agents.get_mut("wave-745-worker-2").unwrap()["supervisor_pid"] = Value::Null;
        let plan = drive_tick_plan(&legacy, &schedule, Some(&reconcile), 8);
        assert!(plan.released.is_empty(), "{:?}", plan.released);
        assert_eq!(plan.dispatch, vec!["flux/C-1".to_string()]);
    }

    /// C-724 (failing first): releasing a claim must never cost work.
    ///
    /// `wave-745` is exactly the case that makes this non-negotiable — its interrupted worker held a
    /// 531-line failing-first test that was never committed. The claim has to go so the story can be
    /// scheduled again; the branch, the checkout and every uncommitted byte in it have to stay. The
    /// two are separate questions and this pins them apart: the released status must free the claim
    /// and must NOT make the wave's disk disposable to any sweep.
    ///
    /// On a runtime because the reclaimer resolves refs through the guarded process boundary.
    #[tokio::test(flavor = "multi_thread")]
    async fn releasing_an_abandoned_claim_leaves_the_story_worktree_and_its_uncommitted_work_alone()
    {
        let (repository, branch, base, commit) =
            story_worktree_with_a_commit("c724-release-safety");
        // The interrupted turn's specification: real work, never committed, invisible to every
        // mechanism that reads `base..HEAD`.
        let uncommitted = repository.join("failing_first_test.rs");
        std::fs::write(
            &uncommitted,
            "// a specification the turn never committed\n",
        )
        .expect("leave uncommitted work behind");

        let dead_pid = reaped_supervisor_pid();
        let mut state = drive_fixture_state();
        state.waves.insert(
            "wave-745".into(),
            json!({
                "id": "wave-745",
                "status": "awaiting-handoffs",
                "items": ["flux/C-575"],
                "topology": {"repositories": [{
                    "id": "flux",
                    "source_root": display_path(&repository),
                    "canonical_ref": "main",
                    "base_commit": base,
                    "stories": [{
                        "board_ref": "flux/C-575",
                        "branch": branch,
                        "base_commit": base,
                        "worktree": display_path(&repository),
                        "handoff": Value::Null,
                    }],
                }]},
            }),
        );
        state.agents.insert(
            "wave-745-worker-1".into(),
            json!({
                "id": "wave-745-worker-1",
                "status": "working",
                "supervisor_pid": dead_pid,
                "assignment": {"wave": "wave-745", "board_ref": "flux/C-575"},
            }),
        );

        // Half one: the claim is gone, so the story is schedulable again.
        let plan = drive_tick_plan(
            &state,
            &drive_fixture_schedule(&["flux/C-575"]),
            Some(&json!({"findings": []})),
            4,
        );
        assert_eq!(
            plan.dispatch,
            vec!["flux/C-575".to_string()],
            "the claim is held against pid {dead_pid}, which no longer exists: {:?}",
            plan.withheld
        );

        // Half two: the status that release writes must not make the wave's disk disposable. Both
        // sweeps are asked directly, because it was `cancelled` — the only status that released a
        // claim before this — that took wave-745's checkout with it.
        let released_status = plan.released[0]["status"]
            .as_str()
            .expect("the release names the status it wrote")
            .to_string();
        assert!(
            !wave_worktrees_are_removable(&released_status),
            "`{released_status}` must not make a story worktree removable"
        );
        assert!(
            !wave_is_reclaimable(&released_status),
            "`{released_status}` must not admit an unattended reclaim sweep"
        );

        let mut wave = state.waves["wave-745"].clone();
        wave["status"] = json!(released_status);
        let reclaimed = reclaim_wave_storage(&wave);
        assert_eq!(
            reclaimed["worktrees_removed"],
            json!([]),
            "a released claim must cost no checkout: {reclaimed}"
        );
        assert_eq!(
            reclaimed["branches"],
            json!([]),
            "a released claim must cost no branch: {reclaimed}"
        );
        assert!(
            uncommitted.is_file(),
            "the interrupted turn's uncommitted specification must survive the release"
        );
        assert_eq!(
            git_output(&repository, &["rev-parse", &branch]).as_deref(),
            Some(commit.as_str()),
            "the story branch must still hold the commit it held before"
        );

        std::fs::remove_dir_all(&repository).ok();
    }

    /// C-724 (failing first): `doctor` detected the condition and prescribed a remedy that did not fix
    /// it.
    ///
    /// It reported `agent-supervisor-gone` for both of wave-745's workers and prescribed cancelling
    /// them. Cancelling both did NOT release the wave's claim; only `flux fleet cancel wave-745` did,
    /// and dispatch went from one item to three. A prescription that leaves its own finding standing
    /// is worse than none, because it spends the operator's trust before it spends their time.
    ///
    /// On a runtime because the branch check resolves refs through the guarded process boundary.
    #[tokio::test(flavor = "multi_thread")]
    async fn doctor_reports_a_claim_held_by_a_wave_whose_supervisor_is_gone() {
        let dead_pid = reaped_supervisor_pid();
        let state = wave_745_fixture(dead_pid);

        let health = fleet_runtime_health(&state);
        let findings = health["findings"]
            .as_array()
            .expect("doctor reports runtime findings as an array");

        // The claim itself is a finding, naming wave, item and the dead pid.
        for item in ["flux/C-575", "flux/C-519"] {
            let claim = findings
                .iter()
                .find(|finding| {
                    finding["check"] == "claim-without-supervisor" && finding["subject"] == item
                })
                .unwrap_or_else(|| panic!("{item} is claimed by a wave with no live supervisor, and doctor must say so: {findings:#?}"));
            let detail = claim["detail"].as_str().unwrap_or_default();
            assert!(detail.contains("wave-745"), "{detail}");
            assert!(detail.contains(&dead_pid.to_string()), "{detail}");
        }

        // And the older finding's prescription names the WAVE. Cancelling the worker is what an
        // operator did, twice, to no effect.
        let agent = findings
            .iter()
            .find(|finding| finding["check"] == "agent-supervisor-gone")
            .expect("the worker finding still stands");
        let fix = agent["fix"].as_str().unwrap_or_default();
        assert!(
            fix.starts_with("flux fleet cancel wave-745 "),
            "the prescription must name the wave whose claim is the problem, not the worker whose \
             cancellation leaves it standing: {fix}"
        );
        assert!(
            !fix.contains("cancel wave-745-worker"),
            "cancelling the worker is the remedy that was tried, twice, to no effect: {fix}"
        );
    }

    /// `C-570`'s real Acceptance, abridged to the criteria that name an artifact.
    ///
    /// One box is ticked — a worker got its failing test established and stopped — so the story's
    /// own record does not settle the question and the artifact gate is the one under test. The
    /// wholly unticked case is [`a_wholly_unticked_acceptance_outranks_a_commit_that_names_the_id`].
    const UNBUILT_STORY: &str = "---\nid: C-570\nstatus: ready\n---\n\n# Report progress\n\n\
         ## Goal\n\nOne bounded durable protocol.\n\n## Acceptance\n\n\
         - [x] Failing first, a blocking native `task` child emits observations but cannot produce a\n\
         \x20     durable, acknowledged progress record.\n\
         - [ ] `AgentReport` has stable report/sequence identities, phase/state and a bounded\n\
         \x20     redacted summary. Persistence returns an acknowledgement and is idempotent.\n\
         - [ ] `candidate_ready` means implementation is frozen for review; `handoff_ready` is\n\
         \x20     host-derived only after both mandatory receipts settle.\n\
         - [ ] Native `task` transports reports through the existing correlated child boundary.\n\
         \x20     `SpawnActivity` remains compatible host telemetry.\n\n## Notes\n\nSee `TaskAgentBackend`.\n";

    /// A single-repository board checkout, as `board reconcile` reports one: bare ids, bare story
    /// filenames. Real git, because the only question that matters is what this tree contains.
    fn story_checkout(label: &str, file: &str, story: &str, sources: &[(&str, &str)]) -> PathBuf {
        let root = reclaim_test_dir(label);
        fs::remove_dir_all(&root).ok();
        fs::create_dir_all(root.join("docs/stories")).expect("stories dir");
        fs::write(root.join("docs/stories").join(file), story).expect("story");
        for (path, body) in sources {
            let target = root.join(path);
            fs::create_dir_all(target.parent().expect("source parent")).expect("source dir");
            fs::write(target, body).expect("source");
        }
        guarded_git(&root, &["init", "--initial-branch=main"]).expect("git init");
        root
    }

    /// C-723 (the story's own regression, failing first): free slots, a ready item, and a reconcile
    /// finding asserting `implementation-landed` for a story whose named symbols are absent.
    ///
    /// The fixture is `C-570`'s own Acceptance, with one box ticked so the story's record cannot
    /// settle it and the tree has to. Its `AgentReport` and `candidate_ready` are in no crate, and
    /// the only trace of the story in Rust is a doc comment naming its id. One symbol the Acceptance
    /// names — `SpawnActivity` — genuinely does exist, which is the point: a partially present set is
    /// not an implementation, and the absent members are what decide.
    #[tokio::test(flavor = "multi_thread")]
    async fn drive_dispatches_a_story_whose_named_symbols_are_absent_from_the_tree() {
        let root = story_checkout(
            "withhold-unbuilt",
            "C-570-agent-progress.md",
            UNBUILT_STORY,
            &[(
                "crates/flux-runtime/src/spawn.rs",
                "pub struct SpawnActivity;\n/// Correlation only; the C-570 report protocol is unbuilt.\npub fn correlate() {}\n",
            )],
        );
        let reconcile = json!({"findings": [{
            "id": "C-570",
            "status": "ready",
            "file": "C-570-agent-progress.md",
            "signals": ["implementation-landed"],
            "transition_path": ["in-progress", "done"],
        }]});

        let schedule = drive_fixture_schedule(&["C-570"]);
        let verified =
            drive_verified_reconcile(&root, &reconcile, &schedule_eligible_items(&schedule));
        let plan = drive_tick_plan(&drive_fixture_state(), &schedule, Some(&verified), 8);

        assert_eq!(
            plan.dispatch,
            vec!["C-570".to_string()],
            "a story whose named symbols are absent dispatches: {:?} / {:?}",
            plan.withheld,
            plan.overridden
        );
        assert!(plan.withheld.is_empty(), "{:?}", plan.withheld);
        assert_eq!(plan.overridden.len(), 1, "{:?}", plan.overridden);

        let detail = plan.overridden[0]["detail"].as_str().expect("a detail");
        assert!(detail.contains("AgentReport"), "{detail}");
        let evidence = plan.overridden[0]["evidence"]
            .as_array()
            .expect("per-artifact evidence")
            .clone();
        let answer = |name: &str| {
            evidence
                .iter()
                .find(|entry| entry["artifact"] == json!(name))
                .map(|entry| entry["present"].clone())
        };
        assert_eq!(answer("AgentReport"), Some(json!(false)), "{evidence:?}");
        assert_eq!(
            answer("SpawnActivity"),
            Some(json!(true)),
            "a symbol that does exist is reported as present, and does not rescue the withhold: {evidence:?}"
        );
        assert_eq!(
            answer("task"),
            None,
            "an English word in backticks is not an artifact: {evidence:?}"
        );
        fs::remove_dir_all(&root).ok();
    }

    /// The other direction, so the gate is not simply disabled: a reviewed story whose named symbol
    /// is really in the tree still withholds, and says what it verified.
    #[tokio::test(flavor = "multi_thread")]
    async fn drive_still_withholds_a_story_whose_acceptance_is_ticked_and_whose_symbol_is_present()
    {
        let story = "---\nid: C-1\nstatus: ready\n---\n\n## Acceptance\n\n\
             - [x] `ReportEnvelope` carries the bounded summary.\n\
             - [x] `crates/flux-runtime/src/report.rs` holds it.\n";
        let root = story_checkout(
            "withhold-built",
            "C-1-report-envelope.md",
            story,
            &[(
                "crates/flux-runtime/src/report.rs",
                "pub struct ReportEnvelope {\n    pub summary: String,\n}\n",
            )],
        );
        let reconcile = json!({"findings": [{
            "id": "C-1",
            "status": "ready",
            "file": "C-1-report-envelope.md",
            "signals": ["acceptance-complete", "implementation-landed"],
            "transition_path": ["in-progress", "done"],
        }]});

        let schedule = drive_fixture_schedule(&["C-1"]);
        let verified =
            drive_verified_reconcile(&root, &reconcile, &schedule_eligible_items(&schedule));
        let plan = drive_tick_plan(&drive_fixture_state(), &schedule, Some(&verified), 8);

        assert!(plan.dispatch.is_empty(), "{:?}", plan.dispatch);
        assert!(plan.overridden.is_empty(), "{:?}", plan.overridden);
        assert_eq!(plan.withheld.len(), 1, "{:?}", plan.withheld);
        assert_eq!(plan.withheld[0]["reason"], "already-built");
        let detail = plan.withheld[0]["detail"].as_str().expect("a detail");
        assert!(detail.contains("2 of 2"), "{detail}");
        assert!(detail.contains("ReportEnvelope"), "{detail}");
        fs::remove_dir_all(&root).ok();
    }

    /// The cheapest gate, and the one that settles both live fixtures: a story that has ticked
    /// nothing is telling you, in its own words, that it still owes everything. No tree is opened —
    /// which is also what keeps a tick affordable across a whole board of findings.
    #[test]
    fn a_wholly_unticked_acceptance_outranks_a_commit_that_names_the_id() {
        let unticked = UNBUILT_STORY.replace("- [x]", "- [ ]");

        let verdict = verify_already_built(
            &json!({"signals": ["implementation-landed"]}),
            &unticked,
            Path::new("/nonexistent-checkout-c723"),
        );

        assert!(!verdict.withhold, "{verdict:?}");
        assert!(verdict.detail.contains("none of the 4"), "{verdict:?}");
        assert_eq!(
            verdict.evidence,
            vec![json!({
                "acceptance_ticked": 0,
                "acceptance_total": 4,
                "reviewed_complete": false,
                // C-739: which source the artifacts would have come from. This story declares no
                // `verify:` handle, so the answer is the backtick scrape — and saying so costs no
                // IO, which is what keeps this gate the cheap one.
                "handle_source": "scraped",
            })],
            "the record settles it before any checkout is read: {verdict:?}"
        );
    }

    /// Reconcile reports on every outstanding item on the board; a tick only ever acts on the ones
    /// its schedule offers. Verification follows the tick, so its cost is the ready pool rather than
    /// the backlog — and an unverified finding still cannot withhold.
    #[tokio::test(flavor = "multi_thread")]
    async fn verification_visits_only_the_findings_this_tick_could_dispatch() {
        let root = story_checkout(
            "verify-scope",
            "C-1-x.md",
            "---\nid: C-1\n---\n\n## Acceptance\n\n- [x] `Present` exists.\n",
            &[("src/present.rs", "pub struct Present;\n")],
        );
        let reconcile = json!({"findings": [
            {"id": "C-1", "file": "C-1-x.md", "signals": ["acceptance-complete"]},
            {"id": "C-2", "file": "C-2-not-on-this-schedule.md", "signals": ["acceptance-complete"]},
        ]});
        let schedule = drive_fixture_schedule(&["C-1"]);

        let verified =
            drive_verified_reconcile(&root, &reconcile, &schedule_eligible_items(&schedule));

        assert_eq!(verified["findings"][0]["withhold"]["verified"], json!(true));
        assert_eq!(
            verified["findings"][1]["withhold"],
            Value::Null,
            "an item this tick cannot dispatch is never opened: {:?}",
            verified["findings"][1]
        );

        // And an unvisited finding is powerless even if the schedule later names it.
        let plan = drive_tick_plan(
            &drive_fixture_state(),
            &drive_fixture_schedule(&["C-2"]),
            Some(&verified),
            8,
        );
        assert_eq!(
            plan.dispatch,
            vec!["C-2".to_string()],
            "{:?}",
            plan.withheld
        );
        fs::remove_dir_all(&root).ok();
    }

    /// A doc comment naming a symbol is a forward reference, not an implementation — the same error
    /// as counting a commit that names an id, one level down.
    #[tokio::test(flavor = "multi_thread")]
    async fn a_symbol_that_appears_only_in_a_comment_is_not_present() {
        let root = story_checkout(
            "artifact-comment",
            "C-2-x.md",
            "---\nid: C-2\n---\n",
            &[(
                "crates/flux-runtime/src/later.rs",
                "/// Superseded once `AgentReport` lands.\n// AgentReport is not here yet.\npub fn placeholder() {}\n",
            )],
        );

        assert_eq!(
            artifact_present_in(&root, "AgentReport"),
            Some(false),
            "a doc comment and a line comment are the only mentions"
        );
        assert_eq!(
            artifact_present_in(&root, "placeholder"),
            Some(true),
            "a real definition on the same line is what presence means"
        );
        assert_eq!(
            artifact_present_in(&root, "crates/flux-runtime/src/later.rs"),
            Some(true)
        );
        assert_eq!(
            artifact_present_in(&root, "crates/flux-runtime/src/absent.rs"),
            Some(false)
        );

        // A checkout git cannot read answers nothing, and nothing is never evidence of absence — so
        // the verdict releases rather than withholding on a question it could not put.
        let unreadable = reclaim_test_dir("artifact-no-git");
        fs::remove_dir_all(&unreadable).ok();
        fs::create_dir_all(&unreadable).expect("bare dir");
        assert_eq!(artifact_present_in(&unreadable, "AgentReport"), None);
        let verdict = verify_already_built(
            &json!({"signals": ["acceptance-complete"]}),
            "## Acceptance\n- [x] `AgentReport` lands.\n",
            &unreadable,
        );
        assert!(!verdict.withhold, "{verdict:?}");
        assert!(
            verdict.detail.contains("could not be checked"),
            "{verdict:?}"
        );

        fs::remove_dir_all(&root).ok();
        fs::remove_dir_all(&unreadable).ok();
    }

    /// What an Acceptance names that a tree can be asked about — and what it does not.
    #[test]
    fn acceptance_artifacts_names_symbols_and_paths_but_never_prose_or_an_id() {
        let scraped = acceptance_evidence(UNBUILT_STORY);
        assert_eq!(scraped.source, AcceptanceHandleSource::Scraped);
        assert_eq!(
            scraped.artifacts,
            vec![
                "AgentReport".to_string(),
                "candidate_ready".to_string(),
                "handoff_ready".to_string(),
                "SpawnActivity".to_string(),
            ],
            "`task` is an English word and `TaskAgentBackend` is outside the Acceptance"
        );
        assert!(
            acceptance_evidence(
                "## Acceptance\n- [ ] `flux fleet drive` writes a `*.flux` file for `C-544`.\n"
            )
            .artifacts
            .is_empty(),
            "a command, a glob and a story id are not artifacts"
        );
        assert_eq!(
            acceptance_evidence(
                "## Acceptance\n- [ ] `.agents/skills/flux-tui/SKILL.md` says so.\n"
            )
            .artifacts,
            vec![".agents/skills/flux-tui/SKILL.md".to_string()]
        );
    }

    /// C-739: a declared handle beats the scrape, and the verdict says which one it stood on.
    ///
    /// The scrape is a guess about what a story meant by its backticks — it reads `AgentReport` out
    /// of the prose and hopes that is the artifact. A criterion that declares `verify:` states it
    /// outright, so that is what gets checked, and `handle_source` records the difference for
    /// whoever reads the withhold later. A handle naming nothing checkable (`cargo build`) falls
    /// back to the scrape rather than to nothing: an empty artifact list is not evidence of absence,
    /// and absence is what releases a story back into the pool.
    #[test]
    fn a_declared_verification_handle_outranks_the_backtick_scrape() {
        let declared = "## Acceptance\n\
                        - [x] `AC-1` The reclaimer reports what it removed.\n      \
                        verify: `cargo test -p flux-cli reclaim_reports_removals`\n\
                        - [x] `AC-2` The prose mentions `SomeSymbol` in passing.\n";
        let evidence = acceptance_evidence(declared);
        assert_eq!(evidence.source, AcceptanceHandleSource::Declared);
        assert_eq!(
            evidence.artifacts,
            vec!["reclaim_reports_removals".to_string()],
            "the declared handle is the artifact; the prose symbol is not consulted at all"
        );

        let unspecific = "## Acceptance\n\
                          - [x] `AC-1` It builds.\n      verify: `cargo build`\n\
                          - [x] `AC-2` `SomeSymbol` exists.\n";
        let evidence = acceptance_evidence(unspecific);
        assert_eq!(evidence.source, AcceptanceHandleSource::Scraped);
        assert_eq!(evidence.artifacts, vec!["SomeSymbol".to_string()]);

        let verdict = verify_already_built(
            &json!({"signals": ["acceptance-complete"]}),
            declared,
            Path::new("/nonexistent-checkout-c739"),
        );
        assert_eq!(verdict.evidence[0]["handle_source"], "declared");
    }

    /// C-739: ids and handles are opt-in, and everything downstream of the parser is unmoved by a
    /// story that declares neither.
    ///
    /// Over a thousand stories predate the scheme. `board done`, `board stats`, `board reconcile`
    /// and the driver all read their acceptance through this one parser, so "additive" has to mean
    /// the counts are byte-identical, not merely similar.
    #[test]
    fn a_story_without_criterion_ids_parses_and_counts_exactly_as_it_always_did() {
        let anonymous = "## Acceptance\n\n- [x] It ships.\n- [ ] It is documented.\n\n## Notes\n- [x] not a criterion\n";
        assert_eq!(checkbox_counts(anonymous, "Acceptance"), (1, 1, 2));
        let contract = section_contract(anonymous, "Acceptance");
        assert!(
            contract.defects.is_empty(),
            "a story is not invalid for predating ids: {:?}",
            contract.defects
        );
        assert_eq!(contract.criteria.len(), 2);
        assert!(contract
            .criteria
            .iter()
            .all(|criterion| criterion.id.is_none()));
        assert!(contract
            .criteria
            .iter()
            .all(|criterion| criterion.verify.is_none()));
        assert_eq!(contract.criteria[0].text, "It ships.");

        let addressed = "## Acceptance\n\n\
                         - [x] `AC-1` It ships.\n      verify: `cargo test -p flux-cli it_ships`\n\
                         - [ ] `AC-4` It is documented.\n";
        assert_eq!(
            checkbox_counts(addressed, "Acceptance"),
            (1, 1, 2),
            "an id and a handle are not extra checkboxes"
        );
        let contract = section_contract(addressed, "Acceptance");
        assert!(contract.defects.is_empty(), "{:?}", contract.defects);
        assert_eq!(contract.criteria[0].id.as_deref(), Some("AC-1"));
        assert_eq!(contract.criteria[0].text, "It ships.");
        assert_eq!(
            contract.criteria[0].verify.as_deref(),
            Some("cargo test -p flux-cli it_ships")
        );
        // Ids are allocated once and never renumbered, so a gap is normal and never closed up.
        assert_eq!(contract.criteria[1].id.as_deref(), Some("AC-4"));
        assert_eq!(contract.criteria[1].verify, None);
    }

    /// C-739: `board check` refuses an id that cannot mean one thing — and nothing else.
    #[test]
    fn check_refuses_a_duplicate_criterion_id_and_ignores_a_story_that_declares_none() {
        let story = |body: &str| Story {
            id: "C-1".to_string(),
            title: "Story".to_string(),
            status: "ready".to_string(),
            file: "C-1-story.md".to_string(),
            pillar: None,
            epic: None,
            design: None,
            areas: Vec::new(),
            note: None,
            priority: Some(1),
            dependencies: Vec::new(),
            // C-741 added the field after C-739 wrote this fixture. The default is what a story
            // that never declares one is read as, which is exactly this fixture's case.
            kind: DEFAULT_STORY_KIND.to_string(),
            body: body.to_string(),
        };

        assert!(
            criterion_contract_errors(&story("## Acceptance\n- [ ] It ships.\n- [ ] It works.\n"))
                .is_empty(),
            "the 1,251 stories that predate ids stay valid"
        );

        let duplicated = criterion_contract_errors(&story(
            "## Acceptance\n- [ ] `AC-1` It ships.\n- [ ] `AC-1` It works.\n",
        ));
        assert_eq!(duplicated.len(), 1, "{duplicated:?}");
        assert!(duplicated[0].contains("C-1: criterion id AC-1 is declared twice"));

        let malformed =
            criterion_contract_errors(&story("## Acceptance\n- [ ] `AC-01` It ships.\n"));
        assert_eq!(malformed.len(), 1, "{malformed:?}");
        assert!(malformed[0].contains("malformed criterion id `AC-01`"));

        let orphan = criterion_contract_errors(&story(
            "## Acceptance\n  verify: `cargo test x`\n- [ ] `AC-1` It ships.\n      verify:\n",
        ));
        assert_eq!(orphan.len(), 2, "{orphan:?}");
        assert!(orphan[0].contains("sits under no criterion"), "{orphan:?}");
        assert!(orphan[1].contains("AC-1 declares an empty"), "{orphan:?}");
    }

    /// C-739: a handle is discharged by what actually ran, not by the claim that it did.
    #[test]
    fn a_declared_handle_is_discharged_only_by_the_validation_that_ran_it() {
        let argv = ["cargo", "test", "-p", "flux-cli", "it_ships"].map(str::to_string);

        let (proven, proof) = discharge_criterion_handle(
            Some("cargo test -p flux-cli it_ships"),
            Path::new("."),
            &argv,
        );
        assert!(proven, "{proof}");

        let (proven, proof) = discharge_criterion_handle(
            Some("cargo test -p flux-cli it_is_documented"),
            Path::new("."),
            &argv,
        );
        assert!(
            !proven,
            "an argv that ran another test proves another criterion"
        );
        assert!(proof.contains("did not run"), "{proof}");

        let (proven, proof) = discharge_criterion_handle(None, Path::new("."), &argv);
        assert!(!proven, "a criterion with no handle is never proven");
        assert!(proof.contains("writer's word"), "{proof}");

        let (proven, _) = discharge_criterion_handle(
            Some("crates/flux-cli/src/board_fleet_cmd.rs"),
            Path::new(env!("CARGO_MANIFEST_DIR"))
                .parent()
                .and_then(Path::parent)
                .expect("workspace root"),
            &argv,
        );
        assert!(
            proven,
            "an artifact handle is answered by the tree, not by the argv"
        );
    }

    /// C-723: a withhold that never ends is a decision nobody reviewed, and `fleet doctor` is where
    /// it stops being invisible. Capacity is excluded — that one resolves itself.
    #[test]
    fn a_ready_item_withheld_tick_after_tick_becomes_a_doctor_finding() {
        let withheld = [
            json!({"item": "flux/C-570", "reason": "already-built", "detail": "verified"}),
            json!({"item": "flux/C-9", "reason": "width", "detail": "8 of 8 slots in use"}),
        ];
        let mut streaks = BTreeMap::new();
        for tick in 1..=DRIVE_WITHHOLD_STREAK_LIMIT {
            streaks = drive_withhold_streaks(&streaks, &withheld, tick);
        }
        assert!(
            !streaks.contains_key("flux/C-9"),
            "capacity is a fact about the fleet, not a judgement about an item: {streaks:?}"
        );
        assert_eq!(streaks["flux/C-570"].ticks, DRIVE_WITHHOLD_STREAK_LIMIT);
        assert_eq!(streaks["flux/C-570"].since_tick, 1);

        let mut state = drive_fixture_state();
        state.drive = Some(DriveRecord {
            ticks: DRIVE_WITHHOLD_STREAK_LIMIT,
            withheld: streaks.clone(),
            ..DriveRecord::default()
        });
        let findings = persistent_withhold_findings(&state);
        assert_eq!(findings.len(), 1, "{findings:?}");
        assert_eq!(findings[0]["check"], "item-withheld-persistently");
        assert_eq!(findings[0]["subject"], "flux/C-570");
        assert!(
            findings[0]["detail"]
                .as_str()
                .is_some_and(|detail| detail.contains("already-built") && detail.contains("5")),
            "{findings:?}"
        );
        assert!(
            findings[0]["fix"]
                .as_str()
                .is_some_and(|fix| !fix.is_empty()),
            "{findings:?}"
        );
        assert!(
            fleet_runtime_health(&state)["healthy"] == json!(false),
            "the runtime verdict carries it"
        );

        // The run ends the moment the item ships, so the finding cannot outlive the problem.
        let cleared = drive_withhold_streaks(&streaks, &[], DRIVE_WITHHOLD_STREAK_LIMIT + 1);
        assert!(cleared.is_empty(), "{cleared:?}");
    }

    /// C-728: the `[[program]]` lanes one milestone needs, written in dispatch order.
    fn program_lanes(items: &[&str]) -> String {
        items
            .iter()
            .enumerate()
            .map(|(index, item)| {
                format!(
                    "\n[[program]]\nid = \"lane-{}\"\nitem = \"{item}\"\nmilestone = \"m1\"\n\
                     order = {}\n",
                    item.replace('/', "-"),
                    (index + 1) * 10
                )
            })
            .collect()
    }

    /// C-728: a workspace board whose milestone program IS the schedulable pool.
    ///
    /// Every named story is written `ready` with no dependency, so what reaches dispatch is decided
    /// by the program and the `[[waves]]` entries alone — which is the exact question this story
    /// asks. No git: `read_workspace_member_stories` falls back to the filesystem when a member's
    /// `canonical_ref` does not resolve, so the fixture stays a directory tree.
    fn program_workspace(
        label: &str,
        members: &[(&str, &[&str])],
        board: &str,
        fleet: &str,
    ) -> PathBuf {
        let root = reclaim_test_dir(label);
        fs::remove_dir_all(&root).ok();
        fs::create_dir_all(root.join(".flux")).expect("flux dir");
        fs::create_dir_all(root.join("decisions")).expect("decisions dir");
        for (member, stories) in members {
            let dir = root.join("members").join(member).join("docs/stories");
            fs::create_dir_all(&dir).expect("stories dir");
            for id in *stories {
                fs::write(
                    dir.join(format!("{id}-fixture.md")),
                    format!(
                        "---\nid: {id}\ntitle: Fixture {id}\nstatus: ready\npriority: 1\n---\n\n\
                         # Fixture {id}\n\n## Acceptance\n\n- [ ] Unbuilt.\n"
                    ),
                )
                .expect("story");
            }
        }
        fs::write(root.join(".flux/board.toml"), board).expect("board config");
        fs::write(root.join(".flux/fleet.toml"), fleet).expect("fleet config");
        root
    }

    /// A workspace board: one `[[members]]` entry per member, the milestone program, then `waves`.
    fn workspace_board(members: &[&str], items: &[&str], waves: &str) -> String {
        let members = members
            .iter()
            .map(|member| {
                format!(
                    "\n[[members]]\nid = \"{member}\"\nroot = \"members/{member}\"\n\
                     board = \"{member}\"\ncanonical_ref = \"HEAD\"\n"
                )
            })
            .collect::<String>();
        format!(
            "schema = \"flux.board-workspace/v1\"\nid = \"program\"\ndefault = true\n\
             active_milestone = \"m1\"\ndecisions = \"decisions\"\n{members}{}\n{waves}",
            program_lanes(items)
        )
    }

    /// A fleet that can cut a worktree in exactly the named repositories and nowhere else.
    fn workspace_fleet(max_workers: usize, max_wave: usize, repositories: &[&str]) -> String {
        let repositories = repositories
            .iter()
            .map(|repository| {
                format!(
                    "\n[[repositories]]\nid = \"{repository}\"\nroot = \"members/{repository}\"\n\
                     board = \"{repository}\"\ncanonical_ref = \"HEAD\"\ngate = [\"true\"]\n"
                )
            })
            .collect::<String>();
        format!(
            "schema = \"flux.fleet/v1\"\nmax_workers = {max_workers}\nmax_wave = {max_wave}\n\
             max_rework = 2\n{repositories}"
        )
    }

    /// Every eligible item this tick either sent or named a reason for.
    fn accounted_for(plan: &DrivePlan) -> BTreeSet<String> {
        plan.dispatch
            .iter()
            .cloned()
            .chain(
                plan.withheld
                    .iter()
                    .filter_map(|entry| entry["item"].as_str().map(str::to_string)),
            )
            .collect()
    }

    /// C-728 (the story's own regression, failing first): the live tick, reproduced.
    ///
    /// Eight free slots, eight program-eligible dependency-satisfied items, and a hand-written
    /// `[[waves]]` entry naming five of them. `flux/C-600`, `flux/C-601` and `flux/C-622` were
    /// `eligible: true` in the milestone program and reached no wave at all, so dispatch — which
    /// draws from `schedule["waves"][…]["eligible"]` — never saw them and the withhold logic never
    /// got the chance to say why. The tick planned five dispatches and recorded nothing about the
    /// other three, which from the outside is indistinguishable from a pool that never held them.
    #[tokio::test(flavor = "multi_thread")]
    async fn drive_dispatches_a_program_eligible_item_that_no_configured_wave_names() {
        let items = [
            "flux/C-595",
            "flux/C-596",
            "flux/C-597",
            "flux/C-598",
            "flux/C-599",
            "flux/C-600",
            "flux/C-601",
            "flux/C-622",
        ];
        let root = program_workspace(
            "unplanned-dispatch",
            &[(
                "flux",
                &[
                    "C-595", "C-596", "C-597", "C-598", "C-599", "C-600", "C-601", "C-622",
                ],
            )],
            &workspace_board(
                &["flux"],
                &items,
                "\n[[waves]]\nid = \"flux-core\"\nstate = \"active\"\nrepository = \"flux\"\n\
                 items = [\"flux/C-595\", \"flux/C-596\", \"flux/C-597\", \"flux/C-598\", \
                 \"flux/C-599\"]\n",
            ),
            &workspace_fleet(8, 10, &["flux"]),
        );

        let schedule = fleet_schedule(&root).expect("a schedule");
        let pool = value_strings(&schedule["program_items"]);
        assert_eq!(pool.len(), 8, "the milestone program holds eight: {pool:?}");

        let plan = drive_tick_plan(
            &drive_fixture_state(),
            &schedule,
            Some(&json!({"findings": []})),
            8,
        );

        assert_eq!(plan.width, 8, "eight workers are free");
        for item in ["flux/C-600", "flux/C-601", "flux/C-622"] {
            assert!(
                plan.dispatch.contains(&item.to_string()),
                "{item} is program-eligible and named by no wave, so it dispatches: {:?} / {:?}",
                plan.dispatch,
                plan.withheld
            );
        }
        assert_eq!(
            plan.dispatch.len(),
            8,
            "eight free slots and eight eligible items fill every slot: {:?}",
            plan.dispatch
        );

        let accounted = accounted_for(&plan);
        for item in &pool {
            assert!(
                accounted.contains(item),
                "{item} left the schedulable pool with no record: {:?} / {:?}",
                plan.dispatch,
                plan.withheld
            );
        }
        fs::remove_dir_all(&root).ok();
    }

    /// C-728: the unit composed for unplanned items obeys the bounds a configured wave obeys, and
    /// every item it cannot carry is named rather than dropped.
    ///
    /// One repository per wave, at most `max_wave` stories. `web` has an eligible item and no
    /// `[[repositories]]` entry, so this fleet could cut it no worktree — that is a reason to
    /// report, not a reason to synthesize a wave that would die at `prepare_wave_worktrees`.
    #[tokio::test(flavor = "multi_thread")]
    async fn an_unplanned_dispatch_unit_holds_one_repository_and_at_most_max_wave_stories() {
        let root = program_workspace(
            "unplanned-bounds",
            &[("flux", &["C-600", "C-601", "C-622"]), ("web", &["C-700"])],
            &workspace_board(
                &["flux", "web"],
                &["flux/C-600", "flux/C-601", "flux/C-622", "web/C-700"],
                "",
            ),
            &workspace_fleet(8, 2, &["flux"]),
        );

        let schedule = fleet_schedule(&root).expect("a schedule");
        let synthesized = schedule["waves"]
            .as_array()
            .expect("waves")
            .iter()
            .filter(|wave| wave["synthesized"] == json!(true))
            .collect::<Vec<_>>();
        assert_eq!(
            synthesized.len(),
            1,
            "one unit per dispatchable repository, and `web` is not one: {synthesized:?}"
        );
        assert_eq!(synthesized[0]["repository"], "flux");
        assert!(
            value_strings(&synthesized[0]["items"])
                .iter()
                .all(|item| item_repository(item) == "flux"),
            "a wave names exactly one repository: {synthesized:?}"
        );
        assert_eq!(
            value_strings(&synthesized[0]["eligible"]),
            vec!["flux/C-600".to_string(), "flux/C-601".to_string()],
            "max_wave is 2, so the third waits: {synthesized:?}"
        );

        let plan = drive_tick_plan(
            &drive_fixture_state(),
            &schedule,
            Some(&json!({"findings": []})),
            8,
        );

        assert_eq!(
            plan.dispatch,
            vec!["flux/C-600".to_string(), "flux/C-601".to_string()],
            "{:?}",
            plan.withheld
        );
        let reason = |item: &str| {
            plan.withheld
                .iter()
                .find(|entry| entry["item"] == json!(item))
                .and_then(|entry| entry["reason"].as_str())
                .map(str::to_string)
        };
        assert_eq!(reason("flux/C-622").as_deref(), Some("wave-capacity"));
        assert_eq!(
            reason("web/C-700").as_deref(),
            Some("repository-unconfigured"),
            "an item this fleet cannot cut a worktree for is named, not dropped: {:?}",
            plan.withheld
        );
        assert!(
            plan.withheld
                .iter()
                .all(|entry| entry["detail"].as_str().is_some_and(|it| !it.is_empty())),
            "every withhold states its reason: {:?}",
            plan.withheld
        );
        let accounted = accounted_for(&plan);
        for item in value_strings(&schedule["program_items"]) {
            assert!(accounted.contains(&item), "{item} left no record");
        }
        fs::remove_dir_all(&root).ok();
    }

    /// C-728: a synthesized unit is bounded by the configured worker width like any other.
    ///
    /// Widening what dispatch can SEE must not widen what it may do. Six free slots, eight eligible
    /// items, and the two that do not fit wait on capacity — a fact about the fleet that resolves
    /// itself — rather than dispatching over the worker ceiling.
    #[tokio::test(flavor = "multi_thread")]
    async fn an_unplanned_item_still_waits_for_a_free_worker_slot() {
        let items = [
            "flux/C-595",
            "flux/C-596",
            "flux/C-597",
            "flux/C-598",
            "flux/C-599",
            "flux/C-600",
            "flux/C-601",
            "flux/C-622",
        ];
        let root = program_workspace(
            "unplanned-width",
            &[(
                "flux",
                &[
                    "C-595", "C-596", "C-597", "C-598", "C-599", "C-600", "C-601", "C-622",
                ],
            )],
            &workspace_board(
                &["flux"],
                &items,
                "\n[[waves]]\nid = \"flux-core\"\nstate = \"active\"\nrepository = \"flux\"\n\
                 items = [\"flux/C-595\", \"flux/C-596\", \"flux/C-597\", \"flux/C-598\", \
                 \"flux/C-599\"]\n",
            ),
            &workspace_fleet(6, 10, &["flux"]),
        );

        let schedule = fleet_schedule(&root).expect("a schedule");
        let plan = drive_tick_plan(
            &drive_fixture_state(),
            &schedule,
            Some(&json!({"findings": []})),
            6,
        );

        assert_eq!(plan.width, 6);
        assert_eq!(plan.dispatch.len(), 6, "{:?}", plan.dispatch);
        assert_eq!(
            plan.withheld
                .iter()
                .filter(|entry| entry["reason"] == json!("width"))
                .count(),
            2,
            "the overflow waits on capacity, and says so: {:?}",
            plan.withheld
        );
        let accounted = accounted_for(&plan);
        for item in value_strings(&schedule["program_items"]) {
            assert!(accounted.contains(&item), "{item} left no record");
        }
        fs::remove_dir_all(&root).ok();
    }

    /// C-728: this widens dispatch; it does not reinterpret a wave an operator composed.
    ///
    /// A `done` wave still owns the items it names, so they are not swept into a synthesized unit
    /// behind the operator's back. The item is reported with the wave that holds it — which is the
    /// difference between a deliberate decision and the silence this story removes.
    #[tokio::test(flavor = "multi_thread")]
    async fn a_hand_configured_wave_still_decides_the_items_it_names() {
        let root = program_workspace(
            "unplanned-configured-wins",
            &[("flux", &["C-600", "C-601"])],
            &workspace_board(
                &["flux"],
                &["flux/C-600", "flux/C-601"],
                "\n[[waves]]\nid = \"flux-retired\"\nstate = \"done\"\nrepository = \"flux\"\n\
                 items = [\"flux/C-600\"]\n",
            ),
            &workspace_fleet(8, 10, &["flux"]),
        );

        let schedule = fleet_schedule(&root).expect("a schedule");
        assert!(
            schedule["waves"]
                .as_array()
                .expect("waves")
                .iter()
                .filter(|wave| wave["synthesized"] == json!(true))
                .all(|wave| !value_strings(&wave["items"]).contains(&"flux/C-600".to_string())),
            "an item a configured wave names is never re-scheduled elsewhere: {:?}",
            schedule["waves"]
        );

        let plan = drive_tick_plan(
            &drive_fixture_state(),
            &schedule,
            Some(&json!({"findings": []})),
            8,
        );

        assert_eq!(plan.dispatch, vec!["flux/C-601".to_string()]);
        assert_eq!(plan.withheld.len(), 1, "{:?}", plan.withheld);
        assert_eq!(plan.withheld[0]["item"], "flux/C-600");
        assert_eq!(plan.withheld[0]["reason"], "wave-done");
        assert!(
            plan.withheld[0]["detail"]
                .as_str()
                .is_some_and(|detail| detail.contains("flux-retired")),
            "the record names the wave that holds it: {:?}",
            plan.withheld
        );
        fs::remove_dir_all(&root).ok();
    }

    /// C-728: an eligible item nothing dispatches, tick after tick, becomes a `fleet doctor`
    /// question — even when no tick ever said why.
    ///
    /// C-723's check reads the withhold map, so it can only report an item some tick judged. The
    /// failure this story fixes produced no judgement at all, so the run is counted from the
    /// eligible pool minus what dispatch sent, which no accounting gap can hide.
    #[test]
    fn an_eligible_item_no_tick_dispatches_becomes_a_doctor_finding() {
        let pool = [
            "flux/C-1".to_string(),
            "flux/C-2".to_string(),
            "flux/C-3".to_string(),
        ];
        let dispatch = ["flux/C-1".to_string()];
        let withheld = [json!({
            "item": "flux/C-2", "reason": "already-built", "detail": "verified"
        })];
        let mut streaks = BTreeMap::new();
        for tick in 1..DRIVE_WITHHOLD_STREAK_LIMIT {
            streaks = drive_undispatched_streaks(&streaks, &pool, &dispatch, &withheld, None, tick);
        }
        let mut state = drive_fixture_state();
        state.drive = Some(DriveRecord {
            ticks: DRIVE_WITHHOLD_STREAK_LIMIT - 1,
            undispatched: streaks.clone(),
            ..DriveRecord::default()
        });
        assert!(
            never_dispatched_findings(&state, &[]).is_empty(),
            "one tick under the limit is still allowed to be transient: {streaks:?}"
        );

        streaks = drive_undispatched_streaks(
            &streaks,
            &pool,
            &dispatch,
            &withheld,
            None,
            DRIVE_WITHHOLD_STREAK_LIMIT,
        );
        assert!(
            !streaks.contains_key("flux/C-1"),
            "a dispatched item has no run: {streaks:?}"
        );
        assert_eq!(streaks["flux/C-3"].ticks, DRIVE_WITHHOLD_STREAK_LIMIT);
        assert_eq!(streaks["flux/C-3"].since_tick, 1);
        assert_eq!(
            streaks["flux/C-3"].reason, None,
            "eligible, unsent and unexplained is the signature this check exists for: {streaks:?}"
        );
        assert_eq!(
            streaks["flux/C-2"].reason.as_deref(),
            Some("already-built"),
            "{streaks:?}"
        );

        state.drive = Some(DriveRecord {
            ticks: DRIVE_WITHHOLD_STREAK_LIMIT,
            withheld: BTreeMap::from([(
                "flux/C-2".to_string(),
                DriveWithhold {
                    reason: "already-built".to_string(),
                    ticks: DRIVE_WITHHOLD_STREAK_LIMIT,
                    since_tick: 1,
                },
            )]),
            undispatched: streaks.clone(),
            ..DriveRecord::default()
        });
        let health = fleet_runtime_health(&state);
        assert!(
            value_strings(&health["checks"]).contains(&"item-never-dispatched".to_string()),
            "the check is declared: {:?}",
            health["checks"]
        );
        let checks_for = |subject: &str| {
            health["findings"]
                .as_array()
                .expect("findings")
                .iter()
                .filter(|finding| finding["subject"] == json!(subject))
                .filter_map(|finding| finding["check"].as_str().map(str::to_string))
                .collect::<Vec<_>>()
        };
        assert_eq!(
            checks_for("flux/C-2"),
            vec!["item-withheld-persistently".to_string()],
            "an item with a named withhold is reported once, with its reason: {:?}",
            health["findings"]
        );
        assert_eq!(
            checks_for("flux/C-3"),
            vec!["item-never-dispatched".to_string()],
            "{:?}",
            health["findings"]
        );
        let detail = health["findings"]
            .as_array()
            .expect("findings")
            .iter()
            .find(|finding| finding["check"] == json!("item-never-dispatched"))
            .and_then(|finding| finding["detail"].as_str())
            .expect("a detail");
        assert!(detail.contains("no tick recorded a reason"), "{detail}");

        // The run ends the moment the item ships, so the finding cannot outlive the problem.
        let cleared = drive_undispatched_streaks(
            &streaks,
            &pool,
            &["flux/C-3".to_string()],
            &[],
            None,
            DRIVE_WITHHOLD_STREAK_LIMIT + 1,
        );
        assert!(!cleared.contains_key("flux/C-3"), "{cleared:?}");

        // A tick that refused outright DID say why. Recording `None` there would report a silence
        // that never happened, and silence is the only thing this check is meant to name.
        let refused = drive_undispatched_streaks(
            &BTreeMap::new(),
            &pool,
            &[],
            &[],
            Some("fleet is stopped; `flux fleet start` before dispatching"),
            1,
        );
        assert_eq!(
            refused["flux/C-1"].reason.as_deref(),
            Some("fleet is stopped; `flux fleet start` before dispatching"),
            "{refused:?}"
        );
    }

    /// One tick under the limit is not yet a finding: a withhold is allowed to be transient.
    #[test]
    fn a_briefly_withheld_item_is_not_a_finding() {
        let withheld = [json!({"item": "flux/C-570", "reason": "claimed", "detail": "wave-9"})];
        let mut streaks = BTreeMap::new();
        for tick in 1..DRIVE_WITHHOLD_STREAK_LIMIT {
            streaks = drive_withhold_streaks(&streaks, &withheld, tick);
        }
        let mut state = drive_fixture_state();
        state.drive = Some(DriveRecord {
            ticks: DRIVE_WITHHOLD_STREAK_LIMIT - 1,
            withheld: streaks,
            ..DriveRecord::default()
        });

        assert!(
            persistent_withhold_findings(&state).is_empty(),
            "{:?}",
            persistent_withhold_findings(&state)
        );
    }

    /// C-631 (R-13, failing first): a wave parked by exhausted rework rounds must come back with its
    /// budget reset. Restoring only the wave left the story `parked` — so the wave could never earn
    /// `handoffs-ready` — and left `rework_attempts` at the ceiling, so the next review parked it again
    /// on its first round and the human's answer bought nothing.
    #[test]
    fn unparking_resets_the_rework_budget_and_frees_the_stories_the_park_froze() {
        let mut wave = json!({
            "status": "parked",
            "topology": {"repositories": [{"stories": [
                {
                    "board_ref": "flux/C-1",
                    "status": "parked",
                    "rework_attempts": 2,
                    "handoff": {"status": "accepted", "commit": "abc123"},
                },
                {"board_ref": "flux/C-2", "status": "handoff-accepted"},
            ]}]},
        });

        let reset = reset_parked_story_budgets(&mut wave);

        let story = &wave["topology"]["repositories"][0]["stories"][0];
        assert_eq!(story["status"], "handoff-accepted");
        assert_eq!(story["rework_attempts"], 0);
        assert_eq!(
            reset.len(),
            1,
            "only the parked story is touched: {reset:?}"
        );
        assert_eq!(reset[0]["item"], "flux/C-1");
        assert_eq!(reset[0]["restored"], true);
        assert_eq!(reset[0]["rework_attempts_cleared"], 2);
        assert_eq!(
            wave["topology"]["repositories"][0]["stories"][1]["status"],
            "handoff-accepted"
        );
    }

    /// A story parked with no accepted handoff has no reviewed state to return to. Its counter still
    /// resets, but the report says the status was left alone rather than inventing one.
    #[test]
    fn unparking_never_invents_a_status_for_a_story_that_holds_no_accepted_handoff() {
        let mut wave = json!({
            "topology": {"repositories": [{"stories": [
                {"board_ref": "flux/C-3", "status": "parked", "rework_attempts": 1},
            ]}]},
        });

        let reset = reset_parked_story_budgets(&mut wave);

        assert_eq!(reset[0]["restored"], false);
        assert_eq!(reset[0]["status"], "parked");
        assert_eq!(reset[0]["rework_attempts_cleared"], 1);
        assert_eq!(
            wave["topology"]["repositories"][0]["stories"][0]["rework_attempts"],
            0
        );
    }

